import random, statistics
T={
'A':dict(A0=2,At=6,As=5,Hbc=7,Hed=6,g=.10),
'B':dict(A0=2,At=5,As=2,Hbc=6,Hed=6,g=.40),
'C':dict(A0=5,At=6,As=6,Hbc=5,Hed=5,g=.00)}
def score(x,h):
 a0,at,ass,ah=(x[k]/8 for k in ('A0','At','As',h)); d=ah-a0
 return at-a0,ass-a0,at-ass,d,d>=.05,(at-ass)/max(.05,d)
for n,x in T.items(): print(n,'as_written=',score(x,'Hbc'),'same_ED=',score(x,'Hed'))
mech=sorted(T,key=lambda n:(score(T[n],'Hbc')[4],score(T[n],'Hbc')[5]),reverse=True)
naive=sorted(T,key=lambda n:score(T[n],'Hbc')[0],reverse=True)
print('mechanism_rank',mech,'naive_rank',naive,'top1_gain',T[mech[0]]['g'],T[naive[0]]['g'])
r=random.Random(2305); rs=[]
for _ in range(10000):
 q=[sum(r.random()<p for _ in range(256))/256 for p in (.25,.65,.35,.75)]
 rs.append((q[1]-q[2])/(q[3]-q[0]))
print('MC mean_R',statistics.mean(rs),'true_R',.6,'bias',statistics.mean(rs)-.6)
print('control_unique_scores',len(set([0.0,0.0,0.0])))
